"""Three structurally distinct original book-cover directions."""
from pathlib import Path
import json
from playwright.sync_api import sync_playwright
from PIL import Image,ImageDraw
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'e-book/design/v07/covers';OUT.mkdir(parents=True,exist_ok=True)
font='''@font-face{font-family:ReaderSans;src:url("file:///C:/Windows/Fonts/NotoSansKR-VF.ttf");font-weight:100 900}@font-face{font-family:ReaderSerif;src:url("file:///C:/Windows/Fonts/NotoSerifKR-VF.ttf");font-weight:100 900}'''
common=font+'''*{box-sizing:border-box}html,body{margin:0}body{font-family:ReaderSans,sans-serif}.book-cover{position:relative;width:900px;height:1280px;overflow:hidden; background:#F5F1E8;color:#142D32}.book-cover p{margin:0}.strap{position:absolute;left:70px;top:65px;font-size:23px;letter-spacing:.04em}.title{position:absolute;left:65px;top:185px;z-index:2;font-size:90px;line-height:1.2;letter-spacing:-.07em;font-weight:800;margin:0}.promise{position:absolute;left:70px;top:590px;font-size:28px;line-height:1.7;letter-spacing:-.035em}.byline{position:absolute;bottom:65px;left:70px;font-size:24px}.edition{position:absolute;right:70px;bottom:65px;font-size:18px}.rule{position:absolute;left:70px;right:70px;top:125px;height:1px;background:currentColor}.motif{position:absolute;left:65px;right:65px;bottom:130px;height:310px}.book-cover svg{width:100%;height:100%;display:block}.book-cover .method{font-size:18px;letter-spacing:.09em;position:absolute;top:710px;left:70px}.c2{background:#142D32;color:#F5F1E8}.c2 .title{font-family:ReaderSerif,serif;font-weight:650;top:175px;font-size:86px;letter-spacing:-.06em}.c2 .promise{top:570px}.c2 .method{color:#BCE5D3;top:705px}.c3 .slab{position:absolute;top:0;bottom:0;right:0;width:200px;background:#A63F21}.c3 .title{font-size:86px;top:235px;max-width:700px}.c3 .strap{top:80px}.c3 .promise{top:650px;font-size:26px;max-width:580px}.c3 .rail{position:absolute;right:55px;top:95px;color:#F5F1E8;writing-mode:vertical-rl;font-size:25px;letter-spacing:.18em}.c3 .motif{left:65px;right:240px;bottom:155px;height:230px}.c3 .edition{right:245px}.c3 .method{top:795px}.review-label{position:absolute;right:70px;top:70px;font-size:18px}.c3 .review-label{display:none}'''
title='<h1 class="title">그래서,<br>이 캠페인<br>계속할까요?</h1>'
meta='<p class="strap">CRM A/B 테스트 실무서</p><p class="byline">허재혁 지음</p><p class="edition">저자 검토본 0.7</p>'
promise='<p class="promise">차이를 발견하는 실험에서<br>실행을 결정하는 방법으로</p><p class="method">맥락항법 제안 / TRI-V 프레임워크</p>'
# These are conceptual navigation diagrams, not invented empirical charts.
a='<section class="book-cover c1">'+meta+'<div class="rule"></div>'+title+promise+'''<div class="motif"><svg viewBox="0 0 770 310" aria-label="비교에서 결정으로 연결되는 세 단계의 개념도"><g fill="none" stroke="#142D32" stroke-width="3"><path d="M0 75H210L330 155H520L650 75H770"/><path d="M0 235H210L330 155H520L650 235H770"/><circle cx="330" cy="155" r="25" fill="#F5F1E8"/><circle cx="520" cy="155" r="25" fill="#BCE5D3"/></g><g font-family="ReaderSans,sans-serif" fill="#142D32"><text x="0" y="50" font-size="55" font-weight="700">A</text><text x="0" y="300" font-size="55" font-weight="700">B</text><text x="510" y="300" font-size="23">비교 → 해석 → 결정</text></g></svg></div></section>'''
b='<section class="book-cover c2">'+meta+'<div class="rule"></div>'+title+promise+'''<div class="motif"><svg viewBox="0 0 770 310" aria-label="평균을 넘어 조건과 판단을 살피는 개념도"><g fill="none" stroke="#BCE5D3" stroke-width="2"><circle cx="170" cy="155" r="110"/><circle cx="385" cy="155" r="110"/><circle cx="600" cy="155" r="110"/><path d="M0 205H770"/></g><g font-family="ReaderSans,sans-serif" fill="#F5F1E8" font-size="27" text-anchor="middle"><text x="170" y="165">정화</text><text x="385" y="165">입체화</text><text x="600" y="165">언어의 전환</text></g></svg></div></section>'''
c='<section class="book-cover c3">'+meta+'<div class="slab"></div><p class="rail">관측한 차이와 도입할 근거는 다르다</p>'+title+promise+'''<div class="motif"><svg viewBox="0 0 560 230" aria-label="성과와 제약을 함께 읽는 판단의 개념도"><g fill="none" stroke="#142D32" stroke-width="3"><rect x="3" y="3" width="175" height="175"/><path d="M40 136L100 65L145 98M240 88H350M330 68L350 88L330 108"/><circle cx="450" cy="90" r="82"/></g><text x="0" y="220" font-family="ReaderSans,sans-serif" fill="#142D32" font-size="24">숫자의 변화</text><text x="390" y="220" font-family="ReaderSans,sans-serif" fill="#142D32" font-size="24">다음 행동</text></svg></div></section>'''
rows=[]
with sync_playwright() as p:
 browser=p.chromium.launch(channel='chrome',headless=True)
 for key,body,label in [('A',a,'편집형 / 비교에서 결정으로'),('B',b,'논지형 / 세 관점의 연결'),('C',c,'실무형 / 숫자와 다음 행동')]:
  f=OUT/f'cover_{key}.html';f.write_text('<!doctype html><html lang="ko"><meta charset="utf-8"><title>'+label+'</title><style>'+common+'</style>'+body+'</html>',encoding='utf-8')
  page=browser.new_page(viewport={'width':900,'height':1280},device_scale_factor=1);page.goto(f.as_uri());page.evaluate('document.fonts.ready');assert not page.evaluate('document.documentElement.scrollWidth>innerWidth');page.screenshot(path=str(OUT/f'cover_{key}.png'));page.close();rows.append({'key':key,'label':label})
 browser.close()
sheet=Image.new('RGB',(1500,820),'#E4E6E2');draw=ImageDraw.Draw(sheet)
for i,row in enumerate(rows):
 im=Image.open(OUT/f"cover_{row['key']}.png");im=im.resize((450,640),Image.Resampling.LANCZOS);sheet.paste(im,(25+i*500,70));draw.text((25+i*500,30),row['key'],fill='#142D32')
sheet.save(OUT/'cover_comparison_v07.png')
(OUT/'cover_styles.css').write_text(common,encoding='utf-8');(OUT/'selected_cover.html').write_text(a,encoding='utf-8');(OUT/'cover_directions.json').write_text(json.dumps({'recommended':'A','approval':'pending','directions':rows,'note':'Conceptual cover motifs, not empirical data. Original composition, not a publisher cover recreation.'},ensure_ascii=False,indent=2),encoding='utf-8');print(str(OUT/'cover_comparison_v07.png'))
